// Package seccompbpf builds the classic-BPF seccomp program that makewand's
// bubblewrap launchers pass via `bwrap --seccomp <fd>`.
//
// The filter is a denylist: it returns EPERM for ptrace, bpf, keyctl,
// process_vm_readv, process_vm_writev and userfaultfd, for any syscall made
// under a foreign audit architecture, and (on x86_64) for every x32-ABI syscall
// number (nr >= 0x40000000), which would otherwise bypass the denylist.
// Everything else is allowed. The program is identical to the one historically
// generated by router.generateSeccompBPFFilter.
package seccompbpf

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"os"
	"runtime"
)

// ErrUnsupportedArch reports that no filter exists for runtime.GOARCH.
var ErrUnsupportedArch = errors.New("seccomp bpf filter unsupported on this architecture")

// Supported reports whether GenerateFilter returns a filter on this build.
func Supported() bool { return len(GenerateFilter()) > 0 }

// GenerateFilter returns the raw little-endian sock_filter array (8 bytes per
// instruction) for linux/amd64 and linux/arm64, or nil on other architectures.
func GenerateFilter() []byte {
	return generate(runtime.GOARCH)
}

func generate(goarch string) []byte {
	const (
		bpfLd           = 0x00
		bpfW            = 0x00
		bpfAbs          = 0x20
		bpfJmp          = 0x05
		bpfJeq          = 0x10
		bpfJge          = 0x30
		bpfK            = 0x00
		bpfRet          = 0x06
		seccompRetErrno = 0x00050000
		seccompRetAllow = 0x7fff0000
		eperm           = 1

		auditArchX86_64  = 0xc000003e
		auditArchAarch64 = 0xc00000b7
	)

	var expectedArch uint32
	var blockedSyscalls []uint32
	isX86_64 := false

	switch goarch {
	case "amd64":
		expectedArch = auditArchX86_64
		blockedSyscalls = []uint32{
			101, // ptrace
			321, // bpf
			250, // keyctl
			310, // process_vm_readv
			311, // process_vm_writev
			323, // userfaultfd
		}
		isX86_64 = true
	case "arm64":
		expectedArch = auditArchAarch64
		blockedSyscalls = []uint32{
			117, // ptrace
			280, // bpf
			219, // keyctl
			270, // process_vm_readv
			271, // process_vm_writev
			282, // userfaultfd
		}
	default:
		return nil
	}

	buf := new(bytes.Buffer)
	stmt := func(code uint16, k uint32) {
		_ = binary.Write(buf, binary.LittleEndian, code)
		_ = binary.Write(buf, binary.LittleEndian, uint8(0))
		_ = binary.Write(buf, binary.LittleEndian, uint8(0))
		_ = binary.Write(buf, binary.LittleEndian, k)
	}
	jmp := func(code uint16, k uint32, jt, jf uint8) {
		_ = binary.Write(buf, binary.LittleEndian, code)
		_ = binary.Write(buf, binary.LittleEndian, jt)
		_ = binary.Write(buf, binary.LittleEndian, jf)
		_ = binary.Write(buf, binary.LittleEndian, k)
	}

	// 1. Load architecture (seccomp_data.arch, offset 4).
	stmt(bpfLd|bpfW|bpfAbs, 4)
	// 2. Foreign architecture -> EPERM.
	jmp(bpfJmp|bpfJeq|bpfK, expectedArch, 1, 0)
	stmt(bpfRet|bpfK, seccompRetErrno|eperm)

	// 3. Load syscall number (seccomp_data.nr, offset 0).
	stmt(bpfLd|bpfW|bpfAbs, 0)

	if len(blockedSyscalls) > 200 {
		return nil // jump offsets below are 8-bit
	}
	n := uint8(len(blockedSyscalls)) //nolint:gosec // G115: bounded above
	if isX86_64 {
		// 4a. x32 ABI (nr | 0x40000000) -> EPERM.
		const x32SyscallBit = 0x40000000
		jmp(bpfJmp|bpfJge|bpfK, x32SyscallBit, n+1, 0)
	}

	// 4b. Denylisted syscalls -> EPERM.
	for i, sc := range blockedSyscalls {
		remaining := n - 1 - uint8(i)
		jmp(bpfJmp|bpfJeq|bpfK, sc, remaining+1, 0)
	}

	// 5. Default allow.
	stmt(bpfRet|bpfK, seccompRetAllow)
	// 6. Blocked: errno EPERM.
	stmt(bpfRet|bpfK, seccompRetErrno|eperm)

	return buf.Bytes()
}

// NewFilterPipe returns the read end of a pipe preloaded with GenerateFilter()
// and already closed for writing, suitable for exec.Cmd.ExtraFiles and
// `bwrap --seccomp <fd>`. The caller closes the returned file after the child
// starts. It returns ErrUnsupportedArch when no filter exists.
func NewFilterPipe() (*os.File, error) {
	filter := GenerateFilter()
	if len(filter) == 0 {
		return nil, ErrUnsupportedArch
	}
	r, w, err := os.Pipe()
	if err != nil {
		return nil, fmt.Errorf("create seccomp pipe: %w", err)
	}
	// The filter (<200 bytes) fits in the pipe buffer, so this cannot block.
	if _, err := w.Write(filter); err != nil {
		_ = w.Close()
		_ = r.Close()
		return nil, fmt.Errorf("write seccomp filter: %w", err)
	}
	if err := w.Close(); err != nil {
		_ = r.Close()
		return nil, fmt.Errorf("close seccomp pipe: %w", err)
	}
	return r, nil
}
